#!/usr/bin/env python3
"""MCP server exposing the SDK docs.

Documents are addressable read-only content, so they are resources:

    galbot-sdk://{machine}/{version}/{language}/{doc}

Two trees answer that URI. This checkout's own docs/ is the current version;
mcp/docs_archive/ holds the frozen snapshots of the older ones, which is why
older versions only have Chinese and no g3.

    python3 mcp/docs_mcp.py          # stdio
    python3 mcp/docs_mcp.py --list   # every URI the two trees yield
"""
from __future__ import annotations

import sys
from pathlib import Path

from mcp.server.mcpserver import MCPServer
from mcp.server.mcpserver.exceptions import ResourceNotFoundError

REPO = Path(__file__).resolve().parents[1]
CURRENT = REPO / "docs"
ARCHIVE = Path(__file__).resolve().parent / "docs_archive"
LANGUAGES = ("zh", "en")  # add one here when the docs add one
VERSION = (REPO / "VERSION").read_text().strip()

app = MCPServer(name="galbot-sdk-docs", version=VERSION)


def _folder(machine: str, version: str) -> Path:
    return CURRENT / machine if version == VERSION else ARCHIVE / machine / version


@app.resource("galbot-sdk://{machine}/{version}/{language}/{doc}", mime_type="text/markdown",
              description=f"One SDK document, e.g. galbot-sdk://g1/{VERSION}/zh/troubleshooting")
def document(machine: str, version: str, language: str, doc: str) -> str:
    path = (_folder(machine, version) / language / f"{doc}.md").resolve()
    # resolve() first, so a ".." in any segment cannot climb out of the trees.
    inside = any(root.resolve() in path.parents for root in (CURRENT, ARCHIVE))
    if language not in LANGUAGES or not path.is_file() or not inside:
        raise ResourceNotFoundError(f"No document {machine}/{version}/{language}/{doc}.")
    return path.read_text(encoding="utf-8")


def uris() -> list[str]:
    """Every URI the template currently resolves to, current version first."""
    found = []
    for machine in sorted(p.name for p in CURRENT.iterdir() if p.is_dir()):
        for language in LANGUAGES:
            for path in sorted((CURRENT / machine / language).glob("*.md")):
                found.append(f"galbot-sdk://{machine}/{VERSION}/{language}/{path.stem}")
    for version_dir in sorted(ARCHIVE.glob("*/*")):
        for language in LANGUAGES:
            for path in sorted((version_dir / language).glob("*.md")):
                machine, version = version_dir.parent.name, version_dir.name
                found.append(f"galbot-sdk://{machine}/{version}/{language}/{path.stem}")
    return found


if __name__ == "__main__":
    if "--list" in sys.argv:
        print("\n".join(uris()))
    else:
        print(f"{len(uris())} documents, SDK {VERSION}", file=sys.stderr)
